INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 11, 'theory', 'Quiz: undefined behavior, debugging and sanitizers');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 11, 0, 'What does the standard guarantee in case of undefined behavior?', '["The program will certainly crash", "Nothing: the program may work, crash, return garbage or behave differently in another compiler version", "The result will always be zero", "The behavior is determined only by the operating system"]', 1, 'UB means no guarantees. The compiler is entitled to assume it never happens, and therefore does not check such cases.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 11, 1, 'Why can the optimizer remove the check if (!p) placed after the line int v = p->a;?', '["Because the condition is written incorrectly", "Because pointers cannot be compared with zero", "Because of a linker bug", "Since p has already been dereferenced, the optimizer may assume p is not NULL, as otherwise it would be UB"]', 3, 'The optimizer reasons by contradiction: a correct program contains no UB, so after a dereference the pointer cannot be null. The check must be placed before the use.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 11, 2, 'Which errors does -fsanitize=address find?', '["Out-of-bounds access on the heap, stack and global data, use-after-free, double free (and leaks)", "Only memory leaks", "Signed integer overflow and shifts", "Data races between threads"]', 0, 'ASan surrounds blocks with red zones and keeps a shadow map. Signed overflow and shifts are caught by UBSan, races by TSan.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 11, 3, 'What is the flag -fno-sanitize-recover=all for when used together with -fsanitize=undefined?', '["To disable the checks", "To speed up the program", "So that the program stops at the first error found instead of continuing", "To also enable MemorySanitizer"]', 2, 'By default UBSan prints a message and continues. In tests you want an immediate failure, otherwise the error is easy to miss among the output.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 11, 4, 'Which flags should you use to build a program for step-by-step debugging in gdb?', '["-O3 -DNDEBUG", "-fsanitize=thread", "-s -O2", "-g -O0: debug information and no optimizations, otherwise variables and lines \"disappear\""]', 3, 'Debug information (-g) maps machine code to lines and variables, while optimizations (-O2) reorder and delete code, so for debugging you use -O0.');
